report_path = Path('dist/functional-report/summary.json')
report = json.loads(report_path.read_text(encoding='utf-8')) if report_path.exists() else {'status':'pending','cases':[]}
passed = {item['id'] for item in report.get('cases', []) if item.get('status') == 'passed'}
for item in rows:
    item['status'] = 'passed' if all(case in passed for case in item['cases']) else 'pending'
transcripts = {}
for path in sorted(Path('dist/functional-report/transcripts').glob('*.json')):
    frames = json.loads(path.read_text(encoding='utf-8'))
    if isinstance(frames, list) and any(frame.get('payload', {}).get('post_type') == 'message' for frame in frames):
        transcripts[path.stem] = frames
payload = json.dumps({'features':rows,'report':report,'transcripts':transcripts}, ensure_ascii=False).replace('<', '\\u003c')
